// GlitchSAT, ext/masking (copied from real/opentitan_prims/shims) (own code, Apache-2.0). Not OpenTitan code.
//
// Stand-in for OpenTitan's abstract primitive `prim_buf` (normally generated by primgen).
// Selects the generic implementation prim_generic_buf (two inverters). Note: the per-module
// `abc` step maps prim_generic_buf to a plain wire, so these buffers add no gates and no
// fault sites. Real OpenTitan synthesis keeps them with size_only/dont_touch constraints.
module prim_buf #(
  parameter int Width = 1
) (
  input        [Width-1:0] in_i,
  output logic [Width-1:0] out_o
);

  prim_generic_buf #(
    .Width (Width)
  ) u_impl (
    .in_i  (in_i),
    .out_o (out_o)
  );

endmodule
